}

def caminho(origem, destino):
    fila = deque([[origem]])
    visitados = {origem}
    while fila:
        rota = fila.popleft()
        if rota[-1] == destino:
            return rota
        for v in grafo[rota[-1]]:
            if v not in visitados:
                visitados.add(v)
                fila.append(rota + [v])

