import heapq

grafo = {
    "A": [("B", 1), ("C", 2)],
    "B": [("D", 5)],
    "C": [("D", 2)],
    "D": [],
}

def dijkstra(origem):
    dist = {v: float("inf") for v in grafo}
    dist[origem] = 0
    fila = [(0, origem)]
    while fila:
        d, v = heapq.heappop(fila)
        if d > dist[v]:
            continue
        for vizinho, peso in grafo[v]:
            if d + peso < dist[vizinho]:
                dist[vizinho] = d + peso
                heapq.heappush(fila, (dist[vizinho], vizinho))
    return dist

print(dijkstra("A")["D"])

