grafo = {
    "A": [("B", 1), ("C", 2)],
    "B": [],
    "C": [("B", -2)],
}

def dijkstra(origem):
    dist = {v: float("inf") for v in grafo}
    dist[origem] = 0
    visitados = set()
    fila = [(0, origem)]
    while fila:
        d, v = heapq.heappop(fila)
        if v in visitados:
            continue
        visitados.add(v)
        for vizinho, peso in grafo[v]:
            if vizinho not in visitados and d + peso < dist[vizinho]:
                dist[vizinho] = d + peso
                heapq.heappush(fila, (dist[vizinho], vizinho))
    return dist

