def bipartido(grafo):
    cor = {}
    for inicio in grafo:
        if inicio in cor:
            continue
        cor[inicio] = 0
        pilha = [inicio]
        while pilha:
            v = pilha.pop()
            for w in grafo[v]:
                if w not in cor:
                    cor[w] = 1 - cor[v]
                    pilha.append(w)
                elif cor[w] == cor[v]:
                    return False
    return True

